-- Migration: Packages table (tour packages, formerly hard-coded in
-- app/tours/tour-data.ts + per-day photos from app/tours/city-highlights.ts).
-- Run this in the Supabase SQL Editor.
--
-- The seed at the bottom carries all 23 original packages over verbatim,
-- including hero images, per-day itinerary photos, journey maps and all tags.
-- It is generated by scripts/generate-package-seed.ts — do not hand-edit the
-- INSERTs; re-run that script instead.

-- 1. Create packages table
CREATE TABLE IF NOT EXISTS packages (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  slug           TEXT NOT NULL UNIQUE,          -- URL code, e.g. /tours/<slug>
  title          TEXT NOT NULL,
  starting_price TEXT,                          -- display string like "$290"; NULL if unpriced
  description    TEXT NOT NULL,                 -- HTML (rendered in a prose container)
  days           JSONB NOT NULL DEFAULT '[]'::jsonb,  -- [{title, description(html), highlights:[{label,image}]}]
  inclusions     TEXT[] NOT NULL DEFAULT '{}',
  images         TEXT[] NOT NULL DEFAULT '{}',  -- ordered; images[0] = card / carousel-first
  map_image      TEXT,                          -- filename (legacy /public) OR full bucket URL
  countries      TEXT[] NOT NULL DEFAULT '{}',
  destinations   TEXT[] NOT NULL DEFAULT '{}',
  themes         TEXT[] NOT NULL DEFAULT '{}',
  religions      TEXT[] NOT NULL DEFAULT '{}',
  activities     TEXT[] NOT NULL DEFAULT '{}',
  sort_order     INTEGER NOT NULL DEFAULT 0,    -- stable list order (seeded to source order)
  is_published   BOOLEAN NOT NULL DEFAULT true,
  created_at     TIMESTAMPTZ DEFAULT now(),
  updated_at     TIMESTAMPTZ DEFAULT now()
);

-- 2. Indexes
CREATE INDEX IF NOT EXISTS idx_packages_published  ON packages(is_published);
CREATE INDEX IF NOT EXISTS idx_packages_sort_order ON packages(sort_order);
CREATE INDEX IF NOT EXISTS idx_packages_slug       ON packages(slug);

-- 3. Enable RLS
ALTER TABLE packages ENABLE ROW LEVEL SECURITY;

-- 4. RLS Policies (matches the Articles model: public sees published rows,
--    any authenticated admin can manage — no allowlist).
DROP POLICY IF EXISTS "Public can view published packages" ON packages;
CREATE POLICY "Public can view published packages"
  ON packages FOR SELECT
  USING (is_published = true);

DROP POLICY IF EXISTS "Authenticated users can manage packages" ON packages;
CREATE POLICY "Authenticated users can manage packages"
  ON packages FOR ALL
  USING (auth.role() = 'authenticated');

-- 5. Seed all 23 packages.
--    ON CONFLICT (slug) DO NOTHING keeps this safely re-runnable: once an admin
--    edits a package in the dashboard, re-running this file will NOT clobber it.

-- 1. 3-day-quick-tour-of-2-cities — 3 Day Quick Tour of 2 Cities
INSERT INTO packages (slug, title, starting_price, description, days, inclusions, images, map_image, countries, destinations, themes, religions, activities, sort_order, is_published)
VALUES (
  $x$3-day-quick-tour-of-2-cities$x$,
  $x$3 Day Quick Tour of 2 Cities$x$,
  $x$$290$x$,
  $x$<p>Duration: 3 days / 2 nights</p><p>Type: Private escorted tour</p><p>Suitable For: Short stays, add ons, couples, families, transit guests</p>$x$,
  $j$[{"title":"Day 1: Arrival / Kandy – The Cultural Heart","description":"<ul><li>Meet &amp; greet at Bandaranaike International Airport</li><li>Scenic drive through lush hill country to Kandy (approx. 3 hrs)</li><li>En-route stops at Pinnawala Elephant Orphanage (optional) or local spice gardens</li><li>Afternoon city tour of Kandy:</li><li>Visit the Temple of the Sacred Tooth Relic (UNESCO)</li><li>Walk around Kandy Lake and explore the Bazaar and Gem Museum</li><li>Evening: enjoy a Traditional Cultural Dance Show</li><li>Overnight in Kandy (Standard – Senani Hotel 4★ / Deluxe – Oak Ray Regency 5★)</li></ul>","highlights":[{"label":"Temple of the Tooth","image":"/KANDY/Temple of the Tooth.jpg"},{"label":"Royal Botanical Garden","image":"/KANDY/Royal Botanical Garden.jpg"},{"label":"Kandy Food Trail","image":"/KANDY/Kandy Food Trail.jpg"},{"label":"Cultural Dance","image":"/KANDY/Cultural Dance.jpg"},{"label":"Meet Artist Rahju","image":"/KANDY/Meet Artist Rahju.jpg"},{"label":"Ceylon Gems","image":"/KANDY/Ceylon Gems.jpg"}]},{"title":"Day 2: Kandy → Colombo – The Vibrant Coastal Capital","description":"<ul><li>Breakfast at hotel and morning visit to Royal Botanical Gardens – Peradeniya</li><li>Stop at Giragama Tea Factory for a tea experience and tasting</li><li>Depart for Colombo (approx. 3 hrs)</li><li>Afternoon city tour:</li><li>Galle Face Green Promenade</li><li>Gangaramaya Temple and Viharamahadevi Park</li><li>Independence Square, Red Mosque, and Lotus Tower view</li><li>Leisure or shopping at Colombo City Centre / One Galle Face Mall</li><li>Overnight in Colombo (Standard – Cinnamon Red 4★ / Deluxe – Cinnamon Grand 5★)</li></ul>","highlights":[{"label":"Galle Face Green","image":"/COLOMBO/Galle Face Green.webp"},{"label":"Gangaramaya Temple","image":"/COLOMBO/Gangaramaya Temple.jpg"},{"label":"Dutch Hospital","image":"/COLOMBO/Dutch Hospital.jpg"},{"label":"Lotus Tower","image":"/COLOMBO/lotustower.jpg"},{"label":"National Museum","image":"/COLOMBO/National Museum.jpg"},{"label":"Rajamaha Temple","image":"/COLOMBO/Rajamaha Temple.jpg"}]},{"title":"Day 3: Departure","description":"<ul><li>Breakfast and leisure until transfer to the airport for onward flight</li></ul>","highlights":[]}]$j$::jsonb,
  ARRAY[$x$Private Driver/Guide$x$, $x$Private Superior Car$x$, $x$Half Board (Breakfast & Dinner)$x$, $x$Airport Drop-off$x$, $x$Airport Pick-up$x$, $x$Tour Consultant$x$]::text[],
  ARRAY[$x$/package_images/SL-3D2N-CTY-01.webp$x$]::text[],
  $x$3 Day Quick Tour of 2 Cities Glimpse of Lanka the Paradise Isle.webp$x$,
  ARRAY[$x$Sri Lanka$x$]::text[],
  ARRAY[$x$Colombo$x$, $x$Pinnawala$x$, $x$Kandy$x$]::text[],
  ARRAY[$x$Culture & Heritage$x$]::text[],
  ARRAY[$x$Buddhism$x$, $x$Islam$x$]::text[],
  ARRAY[$x$City Tour$x$, $x$Cultural Show$x$, $x$Tea Factory Visit$x$, $x$Heritage$x$]::text[],
  0,
  true
)
ON CONFLICT (slug) DO NOTHING;

