  $j$[{"title":"Day 1: Dambulla - Caves, Culture, and Local Life","description":"<ul><li>Visit the Dambulla Cave Temple and explore ancient murals and statues</li><li>Sightseeing around Dambulla with a feel of local village life and rural landscapes</li><li>Watch a cultural dance show in Dambulla with traditional drumming and fire acts</li><li>Evening at leisure and relax at the hotel</li><li>Optional experiences</li><li>Sigiriya Lion Rock climb</li><li>Habarana village tour with bullock cart ride, local lunch, and village interaction</li></ul>","highlights":[{"label":"Golden Cave Temple","image":"/DAMBULLA/goldencavetemple.jpg"},{"label":"Cave Viewpoint","image":"/DAMBULLA/caveviewpoint.jpg"},{"label":"Minneriya National Park","image":"/DAMBULLA/minnertiya national park.jpg"},{"label":"Ironwood Forest","image":"/DAMBULLA/Ironwood Forest.jpg"},{"label":"Morning Rituals","image":"/DAMBULLA/mornign rituyals.jpg"},{"label":"Megalithic Tombs","image":"/DAMBULLA/Megalithic Tombs.jpg"}]},{"title":"Day 2: Cultural Triangle - Polonnaruwa and Wildlife Safari","description":"<ul><li>Explore the Polonnaruwa Ancient Kingdom and walk among historic ruins and sacred</li><li>Visit Minneriya National Park and Lake</li><li>Optional jeep safari at Minneriya, Habarana, or Kaudulla to spot elephants and</li><li>wildlife</li><li>Return to the hotel and unwind</li><li>Optional experiences</li><li>Anuradhapura Ancient City visit</li><li>Additional wild safari options in the area</li></ul>","highlights":[]},{"title":"Day 3: Kandy - Elephants, Viewpoints, and Sacred Temple","description":"<ul><li>Visit Pinnawala Elephant Orphanage and observe rescued elephants</li><li>Stop at Kadugannawa Viewpoint for stunning hill-country views</li><li>Visit the Temple of the Tooth Relic, the most sacred temple in Kandy</li><li>Enjoy a peaceful walk by Kandy Lake</li><li>Optional experiences</li><li>Open Zoo at Pinnawala</li><li>Peradeniya Botanical Garden</li><li>Embekke Wood Carvings</li><li>Bahirawa Kanda Buddha statue viewpoint</li></ul>","highlights":[{"label":"Temple of the Tooth","image":"/KANDY/Temple of the Tooth.jpg"},{"label":"Royal Botanical Garden","image":"/KANDY/Royal Botanical Garden.jpg"},{"label":"Kandy Food Trail","image":"/KANDY/Kandy Food Trail.jpg"},{"label":"Cultural Dance","image":"/KANDY/Cultural Dance.jpg"},{"label":"Meet Artist Rahju","image":"/KANDY/Meet Artist Rahju.jpg"},{"label":"Ceylon Gems","image":"/KANDY/Ceylon Gems.jpg"}]},{"title":"Day 4: Nuwara Eliya - Waterfalls, Tea, and Cool Hills","description":"<ul><li>Stop at Ramboda Waterfall for scenic photos</li><li>Visit Labookellie Tea Factory and learn tea production with fresh tasting</li><li>Drive through tea plantations and enjoy the hill-country scenery</li><li>Relax by Gregory Lake in the cool climate</li><li>Optional experiences</li><li>Hanuman Temple visit</li><li>Hakgala Botanical Garden</li><li>Ambuluwawa Tower for panoramic views</li></ul>","highlights":[{"label":"Scenic Train Ride","image":"/NUWARA ELIYA/Scenic Train Ride.jpg"},{"label":"Tea Experience","image":"/NUWARA ELIYA/Tea Experience.jpg"},{"label":"Horton Plains","image":"/NUWARA ELIYA/Horton Plains.jpg"},{"label":"High Tea Experience","image":"/NUWARA ELIYA/High Tea Experience.jpg"},{"label":"Colonial Architecture","image":"/NUWARA ELIYA/Colonial Architecture.jpg"},{"label":"Seetha Amman Kovil","image":"/NUWARA ELIYA/Seetha Amman Kovil.jpg"}]},{"title":"Day 5: Ella - Nine Arch Bridge and Mountain Views","description":"<ul><li>Explore Ella town and enjoy the relaxed hill vibe</li><li>Visit the iconic Nine Arch Bridge</li><li>Hike Little Adam’s Peak for beautiful viewpoints</li><li>Visit Kubalwela Temple for a calm cultural stop</li><li>Evening at leisure in Ella</li><li>Optional experiences</li><li>Ella train ride experience</li><li>Seetha Amman Temple</li><li>Flying Ravana zipline and adventure activities</li><li>Ella Rock hike</li><li>Ravana Cave exploration</li><li>Lipton’s Seat viewpoint</li><li>Edison Bungalow in Haputale</li></ul>","highlights":[{"label":"Nine Arch Bridge","image":"/ELLA/ninearchbridge.jpg"},{"label":"Scenic Train Ride","image":"/ELLA/Scenictrainride.jpg"},{"label":"Tea Plantation Tours","image":"/ELLA/Teaplantationtours.jpg"},{"label":"Ella Rock","image":"/ELLA/ellarock.jpg"},{"label":"Waterfall Visits","image":"/ELLA/Waterfallvisiots.jpg"},{"label":"Zip-lining","image":"/ELLA/Zip-lining.jpg"}]},{"title":"Day 6: Yala or Udawalawe - Waterfall Stops and Safari","description":"<ul><li>Adventure</li><li>Stop at Ravana Waterfall near Ella</li><li>Visit Buduruwagala ancient rock statues</li><li>Enjoy scenic forest views on the way to the national park region</li><li>Observe Wallawaya paddy fields and rural landscapes</li><li>Go on a jeep safari at Yala (for leopards) or Udawalawe (for wild elephants)</li><li>Optional experiences</li><li>Clay craft center visit to see traditional pottery making</li></ul>","highlights":[{"label":"Sri Lankan Leopard","image":"/YALA/Sri Lankan Leopard.jpg"},{"label":"Sloth Bear","image":"/YALA/Sloth Bear.jpg"},{"label":"Mugger Crocodile","image":"/YALA/Mugger Crocodile.jpg"},{"label":"Elephants in Sri Lanka","image":"/YALA/Elephants in Sri Lanka.jpg"},{"label":"Kataragama Hindu Temple","image":"/YALA/Kataragama Hindu Temple.jpg"},{"label":"Jungle Sundowner","image":"/YALA/Jungle Sundowner.webp"}]},{"title":"Day 7: South Coast - Beaches and Scenic Highlights","description":"<ul><li>Visit Tissa Lake and a Buddhist temple</li><li>Relax at Mirissa Beach</li><li>Visit Coconut Tree Hill for iconic coastal views</li><li>Enjoy Weligama Beach, great for ocean vibes and photos</li><li>Optional experiences</li><li>Kataragama Temple visit</li><li>Whale watching tour in Mirissa (seasonal)</li><li>Surfing in Weligama</li></ul>","highlights":[]},{"title":"Day 8: South Coast - Galle Fort and Hikkaduwa Beach Time","description":"<ul><li>Explore the historic Galle Fort and walk through colonial streets</li><li>Experience Weligama stilt fishing views and photo moments</li><li>Relax at Hikkaduwa Beach, famous for its lively atmosphere and coral reef coast</li><li>Optional experiences</li><li>Water sports in Hikkaduwa such as snorkeling, diving, and reef exploration</li></ul>","highlights":[{"label":"Galle Fort","image":"/GALLE/gallfort.jpg"},{"label":"Historic Streets","image":"/GALLE/historic-streets.jpg"},{"label":"Fort Museums","image":"/GALLE/Fort Museums.jpg"},{"label":"Beach Activities","image":"/GALLE/Beach Activities.jpg"},{"label":"Local Market & Shopping","image":"/GALLE/localmarketshopppign.jpg"},{"label":"Sunset Rampart Walks","image":"/GALLE/sunsetrampartwalks.jpg"}]},{"title":"Day 9: Colombo - Culture, Port City, and City Seaside","description":"<ul><li>Visit Ambalangoda Mask Museum and learn about traditional mask-making</li><li>Enjoy Southern Expressway sightseeing on the way to Colombo</li><li>Visit Galle Face Green for a seaside city stroll</li><li>Visit Port City for modern waterfront views</li><li>Visit Gangaramaya Temple, a unique blend of culture and architecture</li><li>Free time to relax and explore Colombo</li><li>Optional experiences</li><li>Kosgoda Turtle Hatchery</li><li>Madu River safari through mangroves</li><li>Lakshmi Amman Kovil</li><li>Lotus Tower city views</li><li>Colombo National Museum</li></ul>","highlights":[{"label":"Galle Face Green","image":"/COLOMBO/Galle Face Green.webp"},{"label":"Gangaramaya Temple","image":"/COLOMBO/Gangaramaya Temple.jpg"},{"label":"Dutch Hospital","image":"/COLOMBO/Dutch Hospital.jpg"},{"label":"Lotus Tower","image":"/COLOMBO/lotustower.jpg"},{"label":"National Museum","image":"/COLOMBO/National Museum.jpg"},{"label":"Rajamaha Temple","image":"/COLOMBO/Rajamaha Temple.jpg"}]},{"title":"Day 10: Departure - Colombo Shopping and Airport","description":"<ul><li>Transfer</li><li>Enjoy your final hours in Colombo at leisure</li><li>Shopping for souvenirs and gifts</li><li>Transfer to the airport for departure</li></ul>","highlights":[]}]$j$::jsonb,
