  $x$<p>Duration: 11 days / 10 nights</p><p>Type: Private escorted tour</p><p>Suitable For: Family, Couple, Friends</p>$x$,
  $j$[{"title":"Day 1: Arrival - Negombo, Coastal Welcome","description":"<ul><li>Arrival and assistance at the airport, then proceed to Negombo</li><li>Visit St. Mary’s Church in Negombo</li><li>Boat ride along the Hamilton Canal and visit the old Dutch Fort in Negombo</li><li>Visit a nearby fishing village to experience local lifestyle</li><li>Enjoy the evening breeze with a colorful sunset experience</li><li>Relax with a beach walk and enjoy Negombo’s lively nightlife</li><li>Overnight stay in Negombo</li></ul>","highlights":[{"label":"Hamilton Canal","image":"/NEGOMBO/Hamilton Canal.jpg"},{"label":"Muthurajawela Wetland","image":"/NEGOMBO/Muthurajawela Wetland.jpg"},{"label":"Negombo Fish Market","image":"/NEGOMBO/Negombo Fish Market.jpg"},{"label":"Fishing Village Life","image":"/NEGOMBO/Fishing Village Life.jpg"},{"label":"Scenic Sunset","image":"/NEGOMBO/Scenic Sunset.jpg"},{"label":"Sail Boats","image":"/NEGOMBO/Sail Boats.jpg"}]},{"title":"Day 2: Negombo to Sigiriya - Elephants, Viewpoints, and","description":"<ul><li>Village Life</li><li>After breakfast, proceed to Sigiriya</li><li>En route, visit Pinnawala Elephant Orphanage</li><li>Climb Pidurangala Rock for the iconic Sigiriya Lion Rock view</li><li>Village walk to experience Sri Lankan culture and village life</li><li>Enjoy a traditional Sri Lankan boat ride</li><li>Dinner and overnight stay in Sigiriya</li></ul>","highlights":[{"label":"Sigiriya Rock Fortress","image":"/SIGIRIYA/Sigiriya Rock Fortress.jpg"},{"label":"Boat Ride Experience","image":"/SIGIRIYA/Boat Ride Experience.jpg"},{"label":"Safari at Minneriya","image":"/SIGIRIYA/Safari at Minneriya.jpg"},{"label":"Village Experience","image":"/SIGIRIYA/Village Experience.jpg"},{"label":"Piduranagala Rock","image":"/SIGIRIYA/Piduranagala Rock.jpg"},{"label":"Dambulla Cave Temple","image":"/SIGIRIYA/Dambulla Cave Temple.jpg"}]},{"title":"Day 3: Sigiriya - Ancient Kingdom and Wildlife Safari","description":"<ul><li>Breakfast at the hotel</li><li>Optional morning visit to Polonnaruwa, Sri Lanka’s second ancient capital (UNESCO</li><li>World Heritage Site)</li><li>Climb the Sigiriya Rock Fortress, the legendary ancient fortress built on a rock</li><li>Wildlife safari at Minneriya National Park to spot elephants, leopards, and</li><li>other endemic animals</li><li>Dinner and overnight stay in Sigiriya</li></ul>","highlights":[]},{"title":"Day 4: Sigiriya to Kandy - Temples, Spices, and Culture","description":"<ul><li>After breakfast, proceed to Kandy</li><li>Stop at the Dambulla Cave Temple (UNESCO World Heritage Site)</li><li>Visit a spice village and learn about world-famous Ceylon spices</li><li>Visit the Temple of the Tooth Relic, the main attraction in Kandy</li><li>Visit the Royal Botanical Garden in Kandy</li><li>Optional Sri Lankan traditional cultural show (time permitting)</li><li>Dinner and overnight stay in Kandy</li></ul>","highlights":[]},{"title":"Day 5: Kandy to Nuwara Eliya - Tea Country and Sunset by","description":"<ul><li>the Lake</li><li>After breakfast, proceed to Nuwara Eliya</li><li>Optional scenic train ride from Kandy to Nuwara Eliya</li><li>En route near Ramboda, visit Shri Bhakta Hanuman Hindu Temple</li><li>Visit Labukale Tea Garden on the way</li><li>Walk through Gregory Park and enjoy the sunset by Lake Gregory</li><li>Dinner and overnight stay in Nuwara Eliya</li></ul>","highlights":[{"label":"Scenic Train Ride","image":"/NUWARA ELIYA/Scenic Train Ride.jpg"},{"label":"Tea Experience","image":"/NUWARA ELIYA/Tea Experience.jpg"},{"label":"Horton Plains","image":"/NUWARA ELIYA/Horton Plains.jpg"},{"label":"High Tea Experience","image":"/NUWARA ELIYA/High Tea Experience.jpg"},{"label":"Colonial Architecture","image":"/NUWARA ELIYA/Colonial Architecture.jpg"},{"label":"Seetha Amman Kovil","image":"/NUWARA ELIYA/Seetha Amman Kovil.jpg"}]},{"title":"Day 6: Nuwara Eliya - Horton Plains and High Tea","description":"<ul><li>Experience</li><li>Breakfast at the hotel</li><li>Visit Horton Plains National Park</li><li>Visit Seetha Amman Hindu Kovil</li><li>Enjoy high tea at the Grand Hotel</li><li>Dinner and overnight stay in Nuwara Eliya</li></ul>","highlights":[]},{"title":"Day 7: Nuwara Eliya to Yala - Ella Sights and Safari","description":"<ul><li>Adventure</li><li>After breakfast, proceed to Yala</li><li>Visit Ella and the famous Nine Arches Bridge</li><li>Visit Buduruwagala and see the tallest Buddha statue on the island</li><li>3 to 4 hour safari at Yala National Park to explore exotic wildlife</li><li>Optional visit to Kataragama Hindu Temple (if interested and time permits)</li><li>Dinner and overnight stay in Yala</li></ul>","highlights":[]},{"title":"Day 8: Yala to Kalutara - Galle Fort, Stilt Fishing, and River","description":"<ul><li>Safari</li><li>After breakfast, proceed to Bentota and Kalutara area</li><li>Witness Sri Lankan stilt fishermen fishing in the traditional style</li><li>Visit Galle Fort and enjoy a Galle city tour</li><li>Madu River boat safari through beautiful mangroves</li><li>Stop at a fish farm during the river ride and, if you like, try Sri Lankan fish therapy</li><li>Dinner and overnight stay in Kalutara</li></ul>","highlights":[{"label":"Stilt Fisherman","image":"/KALUTARA/Stilt Fisherman.jpg"},{"label":"Galle Fort","image":"/KALUTARA/Galle Fort.jpg"},{"label":"Turtle Conservation","image":"/KALUTARA/Turtle Conservation.jpg"},{"label":"Madu River Safari","image":"/KALUTARA/Madu River Safari.jpg"},{"label":"Water Sport","image":"/KALUTARA/Water Sport.jpg"},{"label":"Isolated Lighthouse","image":"/KALUTARA/Isolated Lighthouse.jpg"}]},{"title":"Day 9: Kalutara - Bawa Estate, Water Sports, Turtles, and","description":"<ul><li>Sunset</li><li>Breakfast at the hotel</li><li>Visit Lunuganga Estate, Geoffrey Bawa’s famous country home</li><li>Optional water sports in Bentota: jet ski, banana boat, tube boating, diving,</li><li>snorkeling, deep-sea fishing</li><li>Visit Kosgoda Turtle Hatchery and learn about sea turtle conservation</li><li>Enjoy a relaxing beach stroll and a spectacular sunset</li><li>Dinner and overnight stay in Kalutara</li></ul>","highlights":[]},{"title":"Day 10: Kalutara to Colombo - City Highlights and","description":"<ul><li>Shopping</li><li>After breakfast, proceed to Colombo</li><li>Visit Gangaramaya Buddhist Temple and admire its cultural and modern</li><li>architectural blend</li><li>Explore Colombo Fort area, including the bazaar, Red Mosque, and Dutch</li><li>Museum</li><li>Shopping time at ODEL, Noritake, House of Fashion, Ceylon tea shops, Sri Lankan</li><li>handicrafts, and more</li><li>Overnight stay in Colombo</li></ul>","highlights":[]},{"title":"Day 11: Departure - Airport Drop-off","description":"<ul><li>Breakfast at the hotel</li><li>Transfer to the airport for departure (as per flight schedule)</li></ul>","highlights":[]}]$j$::jsonb,
