-- 19. ceylon-panorama-journey-12-days — Ceylon Panorama Journey (12 days)
INSERT INTO packages (slug, title, starting_price, description, days, inclusions, images, map_image, countries, destinations, themes, religions, activities, sort_order, is_published)
VALUES (
  $x$ceylon-panorama-journey-12-days$x$,
  $x$Ceylon Panorama Journey (12 days)$x$,
  $x$$1,800$x$,
  $x$<p>Duration: 12 days / 11 nights</p><p>Type: Private escorted tour</p><p>Suitable For: Families, couples, and friends</p>$x$,
  $j$[{"title":"Day 1: Arrival - Negombo","description":"<ul><li>Arrival and assistance at the airport, proceed to Negombo</li><li>Visit St. Mary’s Church in Negombo, often called “Little Rome”</li><li>Boat ride along the Hamilton Canal and visit the old Dutch Fort</li><li>Visit a nearby fishing village to experience local lifestyle</li><li>Optional Ayurvedic spa session (can be pre-arranged)</li><li>Enjoy the evening breeze with a beautiful sunset experience</li><li>Beach walk and enjoy Negombo’s lively nightlife</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[{"label":"Hamilton Canal","image":"/NEGOMBO/Hamilton Canal.jpg"},{"label":"Muthurajawela Wetland","image":"/NEGOMBO/Muthurajawela Wetland.jpg"},{"label":"Negombo Fish Market","image":"/NEGOMBO/Negombo Fish Market.jpg"},{"label":"Fishing Village Life","image":"/NEGOMBO/Fishing Village Life.jpg"},{"label":"Scenic Sunset","image":"/NEGOMBO/Scenic Sunset.jpg"},{"label":"Sail Boats","image":"/NEGOMBO/Sail Boats.jpg"}]},{"title":"Day 2: Negombo to Anuradhapura - Safari and Heritage","description":"<ul><li>After breakfast, proceed to Anuradhapura</li><li>Half-day jeep safari at Wilpattu National Park</li><li>Visit Isurumuniya Temple and admire the Lovers’ Statue, Elephant Pond, and stone</li><li>carvings</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[{"label":"Sacred City","image":"/ANURADHAPURA/sacred city.png"},{"label":"Ruwanwelisaya Stupa","image":"/ANURADHAPURA/ruwanwella maga stupa.png"},{"label":"Jetavana Ruins","image":"/ANURADHAPURA/jetavana ruins.png"},{"label":"Ancient Royal Palace","image":"/ANURADHAPURA/ancient royal palace.png"},{"label":"Sacred Bodhi Tree","image":"/ANURADHAPURA/sacred bow treee.png"},{"label":"Abhayagiri Monasteries","image":"/ANURADHAPURA/Abhayagiri Monasteries.jpg"}]},{"title":"Day 3: Anuradhapura - Sacred City and Sunset at Mihintale","description":"<ul><li>Breakfast at the hotel</li><li>Visit the key ancient sites including:</li><li>Ruwanwelisaya</li><li>Mirisawetiya</li><li>Jetavanaramaya</li><li>Thuparamaya</li><li>Lovamahapaya</li><li>Kuttam Pokuna</li><li>Samadhi Pilimaya</li><li>Satmahal Prasada</li><li>Guard Stone</li><li>See the famous semi-circular stone carving found at the foot of steps in ancient</li><li>Buddhist buildings (moonstone)</li><li>Visit Mihintale, where Buddhism was introduced to Sri Lanka</li><li>Climb Mihintale Rock to witness a stunning sunset</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[]},{"title":"Day 4: Anuradhapura to Sigiriya - Aukana and Rock","description":"<ul><li>Fortress</li><li>After breakfast, proceed to Sigiriya</li><li>Visit the Aukana Temple and admire the towering rock-carved Buddha statue</li><li>Climb the Sigiriya Rock Fortress, the legendary ancient citadel</li><li>Climb Pidurangala Rock for the iconic view of Sigiriya Lion Rock</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[]},{"title":"Day 5: Sigiriya - Polonnaruwa, Village Life, and Minneriya","description":"<ul><li>Safari</li><li>After breakfast at the hotel</li><li>Morning visit to Polonnaruwa, Sri Lanka’s second ancient capital and a UNESCO</li><li>World Heritage Site</li><li>Village walk to experience Sri Lankan culture and village life</li><li>Enjoy a Sri Lankan traditional boat ride</li><li>Wildlife safari at Minneriya National Park to see elephants, leopards, and</li><li>other endemic animals</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[{"label":"Sigiriya Rock Fortress","image":"/SIGIRIYA/Sigiriya Rock Fortress.jpg"},{"label":"Boat Ride Experience","image":"/SIGIRIYA/Boat Ride Experience.jpg"},{"label":"Safari at Minneriya","image":"/SIGIRIYA/Safari at Minneriya.jpg"},{"label":"Village Experience","image":"/SIGIRIYA/Village Experience.jpg"},{"label":"Piduranagala Rock","image":"/SIGIRIYA/Piduranagala Rock.jpg"},{"label":"Dambulla Cave Temple","image":"/SIGIRIYA/Dambulla Cave Temple.jpg"}]},{"title":"Day 6: Sigiriya to Kandy - Culture, Gardens, and Crafts","description":"<ul><li>After breakfast, proceed to Kandy</li><li>Stop at the Dambulla Cave Temple (UNESCO World Heritage Site)</li><li>Spice village tour to learn about world-famous Ceylon spices</li><li>Visit the Temple of the Tooth Relic, Kandy’s main attraction</li><li>Visit the Royal Botanical Garden in Peradeniya</li><li>Watch Sri Lankan handicrafts and batik-making</li><li>Learn about Ceylon gems and craftsmanship</li><li>Optional Sri Lankan traditional cultural show (time permitting)</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[]},{"title":"Day 7: Kandy to Nuwara Eliya - Tea Country and High Tea","description":"<ul><li>After breakfast, proceed to Nuwara Eliya</li><li>Visit Shri Bhakta Hanuman Hindu Temple near Ramboda</li><li>Stop at Ramboda Waterfall for photos</li><li>Stop at Labukale Tea Garden on the way</li><li>Visit Seetha Amman Hindu Kovil</li><li>Enjoy high tea at the Grand Hotel</li><li>Evening walk at Gregory Park and watch the sunset by Lake Gregory</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[{"label":"Scenic Train Ride","image":"/NUWARA ELIYA/Scenic Train Ride.jpg"},{"label":"Tea Experience","image":"/NUWARA ELIYA/Tea Experience.jpg"},{"label":"Horton Plains","image":"/NUWARA ELIYA/Horton Plains.jpg"},{"label":"High Tea Experience","image":"/NUWARA ELIYA/High Tea Experience.jpg"},{"label":"Colonial Architecture","image":"/NUWARA ELIYA/Colonial Architecture.jpg"},{"label":"Seetha Amman Kovil","image":"/NUWARA ELIYA/Seetha Amman Kovil.jpg"}]},{"title":"Day 8: Nuwara Eliya to Yala - Ella Views and Safari","description":"<ul><li>Adventure</li><li>After breakfast, proceed to Yala</li><li>Scenic train ride from Nuwara Eliya to Ella</li><li>Explore Ella and visit the Nine Arches Bridge</li><li>Visit Buduruwagala and see the island’s tallest Buddha statue</li><li>3 to 4 hour safari at Yala National Park to explore exotic wildlife</li><li>Look out for elusive leopards and elephants</li><li>Speak with an experienced trekker to learn about the park’s wildlife and bird species</li><li>Optional visit to Kataragama Hindu Temple (time and interest permitting)</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[]},{"title":"Day 9: Yala to Kalutara - Galle Fort and Madu River","description":"<ul><li>After breakfast, proceed to Bentota and Kalutara area</li><li>Witness Sri Lankan stilt fishermen in their traditional fishing style</li><li>Visit Galle Fort and enjoy a Galle city tour</li><li>Boat ride on the Madu River through mangroves</li><li>Stop at a fish farm during the river ride and, if interested, try Sri Lankan fish therapy</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[{"label":"Stilt Fisherman","image":"/KALUTARA/Stilt Fisherman.jpg"},{"label":"Galle Fort","image":"/KALUTARA/Galle Fort.jpg"},{"label":"Turtle Conservation","image":"/KALUTARA/Turtle Conservation.jpg"},{"label":"Madu River Safari","image":"/KALUTARA/Madu River Safari.jpg"},{"label":"Water Sport","image":"/KALUTARA/Water Sport.jpg"},{"label":"Isolated Lighthouse","image":"/KALUTARA/Isolated Lighthouse.jpg"}]},{"title":"Day 10: Kalutara - Bawa Estate, Turtles, Water Sports,","description":"<ul><li>Sunset</li><li>Breakfast at the hotel</li><li>Visit Lunuganga Estate, the country home of architect Geoffrey Bawa</li><li>Optional water sports in Bentota: jet ski, banana boat, tube boating, diving,</li><li>snorkeling, deep-sea fishing</li><li>Visit the Kosgoda Turtle Hatchery and learn about sea turtle conservation</li><li>Beach stroll and enjoy a spectacular sunset</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[]},{"title":"Day 11: Kalutara to Colombo - City Highlights, Shopping,","description":"<ul><li>Nightlife</li><li>After breakfast, proceed to Colombo</li><li>Visit Gangaramaya Buddhist Temple and admire the blend of culture and modern</li><li>architecture</li><li>Visit Lotus Tower for panoramic views over Colombo</li><li>Stop at Independence Square and Arcade Independence Square</li><li>Visit Galle Face Green and see the Old Parliament building</li><li>Shopping time at ODEL, Noritake, House of Fashion, Ceylon tea shops, Sri Lankan</li><li>handicrafts, and more</li><li>Evening option to visit pubs, clubs, and casinos</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[]},{"title":"Day 12: Departure - Airport Drop-off","description":"<ul><li>Breakfast at the hotel</li><li>Transfer to the airport for departure (as per flight schedule)</li></ul>","highlights":[]}]$j$::jsonb,
