  $x$$4,850$x$,
  $x$<p>Duration: 12 days / 11 nights</p><p>Type: Private honeymoon tour</p><p>Suitable For: Couples</p>$x$,
  $j$[{"title":"Day 1: Arrival - Negombo","description":"<ul><li>Arrival and private transfer to Negombo (Kotugoda area)</li><li>Check in at the hotel and unwind</li><li>Stroll through churches and Grand Street</li><li>Optional sunset boat ride through the Dutch Canal in Muthurajawela Wetland</li><li>Optional Negombo city exploration, also known as “Little Rome”</li><li>Relax and enjoy a calm evening</li></ul>","highlights":[{"label":"Hamilton Canal","image":"/NEGOMBO/Hamilton Canal.jpg"},{"label":"Muthurajawela Wetland","image":"/NEGOMBO/Muthurajawela Wetland.jpg"},{"label":"Negombo Fish Market","image":"/NEGOMBO/Negombo Fish Market.jpg"},{"label":"Fishing Village Life","image":"/NEGOMBO/Fishing Village Life.jpg"},{"label":"Scenic Sunset","image":"/NEGOMBO/Scenic Sunset.jpg"},{"label":"Sail Boats","image":"/NEGOMBO/Sail Boats.jpg"}]},{"title":"Day 2: Negombo to Dambulla","description":"<ul><li>After breakfast, transfer to Dambulla</li><li>En route visit the tranquil Ridi Viharaya Temple</li><li>Arrive and enjoy a relaxed evening at the hotel</li></ul>","highlights":[{"label":"Golden Cave Temple","image":"/DAMBULLA/goldencavetemple.jpg"},{"label":"Cave Viewpoint","image":"/DAMBULLA/caveviewpoint.jpg"},{"label":"Minneriya National Park","image":"/DAMBULLA/minnertiya national park.jpg"},{"label":"Ironwood Forest","image":"/DAMBULLA/Ironwood Forest.jpg"},{"label":"Morning Rituals","image":"/DAMBULLA/mornign rituyals.jpg"},{"label":"Megalithic Tombs","image":"/DAMBULLA/Megalithic Tombs.jpg"}]},{"title":"Day 3: Dambulla - Sigiriya and Pidurangala Romance","description":"<ul><li>Climb Sigiriya Rock Fortress for breathtaking views and ancient history</li><li>Sunset visit to Pidurangala Rock for stunning Sigiriya views and a magical golden-</li><li>hour moment</li></ul>","highlights":[]},{"title":"Day 4: Dambulla - Polonnaruwa and Optional Safari","description":"<ul><li>Visit the ancient city of Polonnaruwa and explore historic ruins</li><li>Optional jeep safari at Minneriya National Park for an unforgettable wildlife</li><li>experience</li></ul>","highlights":[]},{"title":"Day 5: Dambulla to Pussellawa via Kandy","description":"<ul><li>Transfer to the Central Highlands and continue to Pussellawa</li><li>Visit the Temple of the Tooth Relic in Kandy</li><li>Stroll around Kandy Lake</li><li>Visit the Royal Botanical Gardens in Peradeniya</li><li>Continue to Pussellawa and settle in for a peaceful evening</li></ul>","highlights":[]},{"title":"Day 6: Pussellawa - Tea, Waterfalls, and High Tea","description":"<ul><li>Explore Pussellawa at a relaxed pace</li><li>Tea experiences with local tea pluckers</li><li>Visit Geradigini Ella Falls</li><li>Visit Kotmale Reservoir</li><li>Return to the hotel for a delightful high tea by the poolside</li></ul>","highlights":[]},{"title":"Day 7: Pussellawa - Ramayana Trails and Scenic Discoveries","description":"<ul><li>Explore Pussellawa and its romantic Ramayana-era legends</li><li>Morning visit to the Lord Hanuman temple</li><li>Visit Chariot Path and Kadadora Temple</li><li>Explore Kotmale and surrounding scenic areas</li><li>Optional experiences based on time: hidden waterfalls, local temples, and short</li><li>scenic train journeys</li></ul>","highlights":[]},{"title":"Day 8: Pussellawa to Yala via Nuwara Eliya and Ella","description":"<ul><li>Early morning drive to Nuwara Eliya to explore “Little England”</li><li>Scenic train journey to Ella</li><li>Visit the iconic Nine Arches Bridge for photos</li><li>Capture moments at the Ella Swing</li><li>Relax at Ravana Pool Club</li><li>Continue the drive to Yala and check in</li></ul>","highlights":[{"label":"Scenic Train Ride","image":"/NUWARA ELIYA/Scenic Train Ride.jpg"},{"label":"Tea Experience","image":"/NUWARA ELIYA/Tea Experience.jpg"},{"label":"Horton Plains","image":"/NUWARA ELIYA/Horton Plains.jpg"},{"label":"High Tea Experience","image":"/NUWARA ELIYA/High Tea Experience.jpg"},{"label":"Colonial Architecture","image":"/NUWARA ELIYA/Colonial Architecture.jpg"},{"label":"Seetha Amman Kovil","image":"/NUWARA ELIYA/Seetha Amman Kovil.jpg"}]},{"title":"Day 9: Yala - Wildlife Adventure","description":"<ul><li>Jeep safari in Yala National Park</li><li>Spot wildlife such as elephants, leopards, deer, and birdlife (sightings depend on</li><li>the day)</li><li>Return to the hotel and enjoy a relaxed evening</li></ul>","highlights":[{"label":"Sri Lankan Leopard","image":"/YALA/Sri Lankan Leopard.jpg"},{"label":"Sloth Bear","image":"/YALA/Sloth Bear.jpg"},{"label":"Mugger Crocodile","image":"/YALA/Mugger Crocodile.jpg"},{"label":"Elephants in Sri Lanka","image":"/YALA/Elephants in Sri Lanka.jpg"},{"label":"Kataragama Hindu Temple","image":"/YALA/Kataragama Hindu Temple.jpg"},{"label":"Jungle Sundowner","image":"/YALA/Jungle Sundowner.webp"}]},{"title":"Day 10: Yala to Galle - Coastal Icons","description":"<ul><li>Transfer to Galle</li><li>Stop at Coconut Tree Hill in Mirissa for iconic views</li><li>Visit the stilt fishermen in Ahangama</li><li>Optional: try the stilt fishing pose if weather and conditions allow</li><li>Arrive in Galle and enjoy the coastal atmosphere</li></ul>","highlights":[{"label":"Galle Fort","image":"/GALLE/gallfort.jpg"},{"label":"Historic Streets","image":"/GALLE/historic-streets.jpg"},{"label":"Fort Museums","image":"/GALLE/Fort Museums.jpg"},{"label":"Beach Activities","image":"/GALLE/Beach Activities.jpg"},{"label":"Local Market & Shopping","image":"/GALLE/localmarketshopppign.jpg"},{"label":"Sunset Rampart Walks","image":"/GALLE/sunsetrampartwalks.jpg"}]},{"title":"Day 11: Galle - Fort Walk and Sundowner","description":"<ul><li>Guided walk inside the Royal Dutch Fort in Galle</li><li>Visit the Dutch Reformed Church</li><li>Enjoy sundowners at Galle Fort with stunning rampart views</li></ul>","highlights":[]},{"title":"Day 12: Departure - Airport Drop-off","description":"<ul><li>Breakfast at the hotel</li><li>Free time depending on flight schedule</li><li>Private transfer to the airport for departure</li></ul>","highlights":[]}]$j$::jsonb,
