  $j$[{"title":"Day 1: Arrival - Negombo","description":"<ul><li>Arrive in Sri Lanka</li><li>Transfer to Negombo</li><li>Warm welcome by your representative</li><li>Welcome meeting at 6:00 pm</li><li>Dinner at the hotel</li><li>Overnight stay in Negombo</li></ul>","highlights":[{"label":"Hamilton Canal","image":"/NEGOMBO/Hamilton Canal.jpg"},{"label":"Muthurajawela Wetland","image":"/NEGOMBO/Muthurajawela Wetland.jpg"},{"label":"Negombo Fish Market","image":"/NEGOMBO/Negombo Fish Market.jpg"},{"label":"Fishing Village Life","image":"/NEGOMBO/Fishing Village Life.jpg"},{"label":"Scenic Sunset","image":"/NEGOMBO/Scenic Sunset.jpg"},{"label":"Sail Boats","image":"/NEGOMBO/Sail Boats.jpg"}]},{"title":"Day 2: Negombo to Dambulla - Village Life and Local","description":"<ul><li>Experiences</li><li>Visit the Negombo Fish Market</li><li>Proceed to Dambulla</li><li>Visit a coconut plantation</li><li>Enjoy a bullock cart ride</li><li>Glide across the lake by catamaran</li><li>Traditional village tour with a local lunch</li><li>Overnight stay in Dambulla</li></ul>","highlights":[{"label":"Golden Cave Temple","image":"/DAMBULLA/goldencavetemple.jpg"},{"label":"Cave Viewpoint","image":"/DAMBULLA/caveviewpoint.jpg"},{"label":"Minneriya National Park","image":"/DAMBULLA/minnertiya national park.jpg"},{"label":"Ironwood Forest","image":"/DAMBULLA/Ironwood Forest.jpg"},{"label":"Morning Rituals","image":"/DAMBULLA/mornign rituyals.jpg"},{"label":"Megalithic Tombs","image":"/DAMBULLA/Megalithic Tombs.jpg"}]},{"title":"Day 3: Anuradhapura and Minneriya - Ancient Capital and","description":"<ul><li>Safari</li><li>Explore Sri Lanka’s 1st ancient capital, Anuradhapura</li><li>Visit the sacred Sri Maha Bodhi Tree</li><li>Explore historical stupas and ancient sites</li><li>Afternoon safari in Minneriya National Park</li><li>Overnight stay in Dambulla</li></ul>","highlights":[{"label":"Sacred City","image":"/ANURADHAPURA/sacred city.png"},{"label":"Ruwanwelisaya Stupa","image":"/ANURADHAPURA/ruwanwella maga stupa.png"},{"label":"Jetavana Ruins","image":"/ANURADHAPURA/jetavana ruins.png"},{"label":"Ancient Royal Palace","image":"/ANURADHAPURA/ancient royal palace.png"},{"label":"Sacred Bodhi Tree","image":"/ANURADHAPURA/sacred bow treee.png"},{"label":"Abhayagiri Monasteries","image":"/ANURADHAPURA/Abhayagiri Monasteries.jpg"}]},{"title":"Day 4: Polonnaruwa and Sigiriya - Heritage and Sunset","description":"<ul><li>Explore Sri Lanka’s 2nd ancient capital, Polonnaruwa</li><li>Climb Sigiriya Rock Fortress at sunset</li><li>Overnight stay in Dambulla</li></ul>","highlights":[{"label":"Sigiriya Rock Fortress","image":"/SIGIRIYA/Sigiriya Rock Fortress.jpg"},{"label":"Boat Ride Experience","image":"/SIGIRIYA/Boat Ride Experience.jpg"},{"label":"Safari at Minneriya","image":"/SIGIRIYA/Safari at Minneriya.jpg"},{"label":"Village Experience","image":"/SIGIRIYA/Village Experience.jpg"},{"label":"Piduranagala Rock","image":"/SIGIRIYA/Piduranagala Rock.jpg"},{"label":"Dambulla Cave Temple","image":"/SIGIRIYA/Dambulla Cave Temple.jpg"}]},{"title":"Day 5: Dambulla to Kandy - Caves, Spices, Lake Walk,","description":"<ul><li>and Culture</li><li>Visit the Dambulla Cave Temple</li><li>Explore a spice garden in Matale</li><li>Stroll by Kandy Lake at dusk</li><li>Visit a gem lapidary</li><li>Enjoy a Kandyan dancing performance</li><li>Overnight stay in Kandy</li></ul>","highlights":[]},{"title":"Day 6: Kandy - Gardens, Heritage, Temple, and Street Food","description":"<ul><li>Visit the Royal Botanical Garden</li><li>Tour the Suriyakantha Center for Kandyan heritage</li><li>Visit the Temple of the Tooth Relic</li><li>Street food stroll in Kandy</li><li>Overnight stay in Kandy</li></ul>","highlights":[{"label":"Temple of the Tooth","image":"/KANDY/Temple of the Tooth.jpg"},{"label":"Royal Botanical Garden","image":"/KANDY/Royal Botanical Garden.jpg"},{"label":"Kandy Food Trail","image":"/KANDY/Kandy Food Trail.jpg"},{"label":"Cultural Dance","image":"/KANDY/Cultural Dance.jpg"},{"label":"Meet Artist Rahju","image":"/KANDY/Meet Artist Rahju.jpg"},{"label":"Ceylon Gems","image":"/KANDY/Ceylon Gems.jpg"}]},{"title":"Day 7: Kandy to Nuwara Eliya - Scenic Train and High Tea","description":"<ul><li>Scenic train ride to Nuwara Eliya (subject to availability)</li><li>High tea experience at the Grand Hotel</li><li>Tour a tea factory and tea plantation</li><li>Overnight stay in Nuwara Eliya</li></ul>","highlights":[{"label":"Scenic Train Ride","image":"/NUWARA ELIYA/Scenic Train Ride.jpg"},{"label":"Tea Experience","image":"/NUWARA ELIYA/Tea Experience.jpg"},{"label":"Horton Plains","image":"/NUWARA ELIYA/Horton Plains.jpg"},{"label":"High Tea Experience","image":"/NUWARA ELIYA/High Tea Experience.jpg"},{"label":"Colonial Architecture","image":"/NUWARA ELIYA/Colonial Architecture.jpg"},{"label":"Seetha Amman Kovil","image":"/NUWARA ELIYA/Seetha Amman Kovil.jpg"}]},{"title":"Day 8: Horton Plains and Nuwara Eliya - Nature and City","description":"<ul><li>Optional trek at Horton Plains National Park</li><li>Nuwara Eliya city walk</li><li>Overnight stay in Nuwara Eliya</li></ul>","highlights":[]},{"title":"Day 9: Ella - Cooking Class, Bridge Visit, and Viewpoint","description":"<ul><li>Sri Lankan cooking class in Ella</li><li>Visit the Nine Arches Bridge</li><li>Hike to Little Adam’s Peak</li><li>Overnight stay in the Yala area</li></ul>","highlights":[{"label":"Nine Arch Bridge","image":"/ELLA/ninearchbridge.jpg"},{"label":"Scenic Train Ride","image":"/ELLA/Scenictrainride.jpg"},{"label":"Tea Plantation Tours","image":"/ELLA/Teaplantationtours.jpg"},{"label":"Ella Rock","image":"/ELLA/ellarock.jpg"},{"label":"Waterfall Visits","image":"/ELLA/Waterfallvisiots.jpg"},{"label":"Zip-lining","image":"/ELLA/Zip-lining.jpg"}]},{"title":"Day 10: Yala - Game Drive and Holy City Visit","description":"<ul><li>Game drive in Yala National Park</li><li>Visit Kataragama Holy City</li><li>Overnight stay in the Yala area</li></ul>","highlights":[{"label":"Sri Lankan Leopard","image":"/YALA/Sri Lankan Leopard.jpg"},{"label":"Sloth Bear","image":"/YALA/Sloth Bear.jpg"},{"label":"Mugger Crocodile","image":"/YALA/Mugger Crocodile.jpg"},{"label":"Elephants in Sri Lanka","image":"/YALA/Elephants in Sri Lanka.jpg"},{"label":"Kataragama Hindu Temple","image":"/YALA/Kataragama Hindu Temple.jpg"},{"label":"Jungle Sundowner","image":"/YALA/Jungle Sundowner.webp"}]},{"title":"Day 11: Yala to Galle - Elephants, Stilt Fishing, and Fort","description":"<ul><li>Visit the Elephant Transit Home</li><li>Visit stilt fishermen in Ahangama</li><li>Explore Galle Fort</li><li>Overnight stay in Galle</li></ul>","highlights":[{"label":"Galle Fort","image":"/GALLE/gallfort.jpg"},{"label":"Historic Streets","image":"/GALLE/historic-streets.jpg"},{"label":"Fort Museums","image":"/GALLE/Fort Museums.jpg"},{"label":"Beach Activities","image":"/GALLE/Beach Activities.jpg"},{"label":"Local Market & Shopping","image":"/GALLE/localmarketshopppign.jpg"},{"label":"Sunset Rampart Walks","image":"/GALLE/sunsetrampartwalks.jpg"}]},{"title":"Day 12: Bentota - Beach Day, Turtles, and River Safari","description":"<ul><li>Beach day in Bentota</li><li>Visit a turtle conservation project</li><li>Madu River boat safari</li><li>Overnight stay in Bentota</li></ul>","highlights":[{"label":"Beach Relaxation","image":"/BENTOTA/Beach Relaxation.jpg"},{"label":"Kosgoda Turtle Hatchery","image":"/BENTOTA/Kosgoda Turtle Hatchery.jpg"},{"label":"Water Sports","image":"/BENTOTA/WaterSports .jpg"},{"label":"Bentota Sanctuary","image":"/BENTOTA/bentota-sanctuary.png"},{"label":"Spa & Wellness","image":"/BENTOTA/spa-inn-desk-feat-1.jpg"},{"label":"Madu River Safari","image":"/BENTOTA/Screenshot 2026-03-27 081945.png"}]},{"title":"Day 13: Colombo - City Tour, Bazaar Walk, and Farewell","description":"<ul><li>Dinner</li><li>Guided city tour of Colombo</li><li>Walking tour of the Colombo bazaar</li><li>Farewell dinner in Colombo</li><li>Overnight stay in Colombo</li></ul>","highlights":[{"label":"Galle Face Green","image":"/COLOMBO/Galle Face Green.webp"},{"label":"Gangaramaya Temple","image":"/COLOMBO/Gangaramaya Temple.jpg"},{"label":"Dutch Hospital","image":"/COLOMBO/Dutch Hospital.jpg"},{"label":"Lotus Tower","image":"/COLOMBO/lotustower.jpg"},{"label":"National Museum","image":"/COLOMBO/National Museum.jpg"},{"label":"Rajamaha Temple","image":"/COLOMBO/Rajamaha Temple.jpg"}]},{"title":"Day 14: Departure - Airport Drop-off","description":"<ul><li>Breakfast at the hotel</li><li>Transfer to the airport for departure (as per flight schedule)</li></ul>","highlights":[]}]$j$::jsonb,
