-- 22. sri-lanka-grand-discovery-tour-13-days — Sri Lanka Grand Discovery Tour (13 days)
INSERT INTO packages (slug, title, starting_price, description, days, inclusions, images, map_image, countries, destinations, themes, religions, activities, sort_order, is_published)
VALUES (
  $x$sri-lanka-grand-discovery-tour-13-days$x$,
  $x$Sri Lanka Grand Discovery Tour (13 days)$x$,
  $x$$1,880$x$,
  $x$<p>Duration: 13 days / 12 nights</p><p>Type: Private escorted tour</p><p>Suitable For: Anyone</p>$x$,
  $j$[{"title":"Day 1: Arrival - Negombo","description":"<ul><li>Arrival and assistance at the airport, proceed to Negombo</li><li>Explore St. Mary’s Church in Negombo, the heart of “Little Rome”</li><li>Enjoy a boat ride on Hamilton Canal and visit the old Dutch Fort in Negombo</li><li>Visit a fishing village for a glimpse of authentic local life</li><li>Enjoy the evening breeze with a stunning sunset sky</li><li>Overnight stay at the hotel</li></ul>","highlights":[{"label":"Hamilton Canal","image":"/NEGOMBO/Hamilton Canal.jpg"},{"label":"Muthurajawela Wetland","image":"/NEGOMBO/Muthurajawela Wetland.jpg"},{"label":"Negombo Fish Market","image":"/NEGOMBO/Negombo Fish Market.jpg"},{"label":"Fishing Village Life","image":"/NEGOMBO/Fishing Village Life.jpg"},{"label":"Scenic Sunset","image":"/NEGOMBO/Scenic Sunset.jpg"},{"label":"Sail Boats","image":"/NEGOMBO/Sail Boats.jpg"}]},{"title":"Day 2: Negombo to Anuradhapura - Sacred City and","description":"<ul><li>Optional Safari</li><li>After breakfast, proceed to Anuradhapura</li><li>Discover Anuradhapura’s sacred highlights, from towering stupas and ancient ponds</li><li>to the serene Samadhi Buddha</li><li>See the Lovers’ Statue and stone carvings at Isurumuniya Temple</li><li>Optional: Half-day jeep safari at Wilpattu National Park</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[{"label":"Sacred City","image":"/ANURADHAPURA/sacred city.png"},{"label":"Ruwanwelisaya Stupa","image":"/ANURADHAPURA/ruwanwella maga stupa.png"},{"label":"Jetavana Ruins","image":"/ANURADHAPURA/jetavana ruins.png"},{"label":"Ancient Royal Palace","image":"/ANURADHAPURA/ancient royal palace.png"},{"label":"Sacred Bodhi Tree","image":"/ANURADHAPURA/sacred bow treee.png"},{"label":"Abhayagiri Monasteries","image":"/ANURADHAPURA/Abhayagiri Monasteries.jpg"}]},{"title":"Day 3: Anuradhapura to Sigiriya - Rock Temples and","description":"<ul><li>Viewpoints</li><li>After breakfast, proceed to Sigiriya</li><li>Marvel at the towering giant Buddha carved from solid rock at Aukana Temple</li><li>Climb the legendary Sigiriya Rock Fortress</li><li>Climb Pidurangala Rock for stunning views of Sigiriya Lion Rock</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[]},{"title":"Day 4: Sigiriya - Ancient City, Village Life, and Safari","description":"<ul><li>After breakfast at the hotel</li><li>Optional: Visit Polonnaruwa, Sri Lanka’s second ancient capital and a UNESCO World</li><li>Heritage Site</li><li>Walk through a serene village to experience authentic Sri Lankan daily life</li><li>Enjoy a scenic traditional Sri Lankan boat ride</li><li>Wildlife safari in Minneriya National Park to spot elephants, leopards, and</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[{"label":"Sigiriya Rock Fortress","image":"/SIGIRIYA/Sigiriya Rock Fortress.jpg"},{"label":"Boat Ride Experience","image":"/SIGIRIYA/Boat Ride Experience.jpg"},{"label":"Safari at Minneriya","image":"/SIGIRIYA/Safari at Minneriya.jpg"},{"label":"Village Experience","image":"/SIGIRIYA/Village Experience.jpg"},{"label":"Piduranagala Rock","image":"/SIGIRIYA/Piduranagala Rock.jpg"},{"label":"Dambulla Cave Temple","image":"/SIGIRIYA/Dambulla Cave Temple.jpg"}]},{"title":"Day 5: Sigiriya to Kandy - Caves, Temple, Gardens, and","description":"<ul><li>After breakfast, proceed to Kandy</li><li>En route, explore the UNESCO-listed Dambulla Cave Temple</li><li>Visit the world-famous Temple of the Tooth Relic, Kandy’s main attraction</li><li>Explore the serene Royal Botanical Garden in Kandy</li><li>Learn about the famous Ceylon gems</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[]},{"title":"Day 6: Kandy to Ella - Scenic Train and Sunset Moments","description":"<ul><li>After breakfast, proceed to Ella</li><li>Scenic train ride from Nanu Oya to Ella, one of the world’s most beautiful journeys</li><li>Visit Ella’s iconic Nine Arch Bridge</li><li>Relax at Ravana Pool Club with a sunset cocktail</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[{"label":"Temple of the Tooth","image":"/KANDY/Temple of the Tooth.jpg"},{"label":"Royal Botanical Garden","image":"/KANDY/Royal Botanical Garden.jpg"},{"label":"Kandy Food Trail","image":"/KANDY/Kandy Food Trail.jpg"},{"label":"Cultural Dance","image":"/KANDY/Cultural Dance.jpg"},{"label":"Meet Artist Rahju","image":"/KANDY/Meet Artist Rahju.jpg"},{"label":"Ceylon Gems","image":"/KANDY/Ceylon Gems.jpg"}]},{"title":"Day 7: Ella - Tea Trails and Adventure","description":"<ul><li>After breakfast at the hotel</li><li>Visit the charming tea plantations in Ella</li><li>Hike Little Adam’s Peak through scenic tea plantations</li><li>Enjoy a thrilling zip line ride over Ella’s landscapes</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[{"label":"Nine Arch Bridge","image":"/ELLA/ninearchbridge.jpg"},{"label":"Scenic Train Ride","image":"/ELLA/Scenictrainride.jpg"},{"label":"Tea Plantation Tours","image":"/ELLA/Teaplantationtours.jpg"},{"label":"Ella Rock","image":"/ELLA/ellarock.jpg"},{"label":"Waterfall Visits","image":"/ELLA/Waterfallvisiots.jpg"},{"label":"Zip-lining","image":"/ELLA/Zip-lining.jpg"}]},{"title":"Day 8: Ella to Yala - Safari Day","description":"<ul><li>After breakfast, proceed to Yala</li><li>Enjoy a safari in Yala National Park, spotting exotic wildlife in their natural habitat</li><li>Keep your eyes peeled to catch a glimpse of elusive leopards</li><li>Get up close with majestic elephants on your safari jeep adventure</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[]},{"title":"Day 9: Yala - Culture and Wildlife Encounters","description":"<ul><li>After breakfast at the hotel</li><li>Optional: Ride 40 km to sacred Kataragama through scenic backroads, ancient</li><li>ruins, and rich wildlife</li><li>See baby elephants rehabilitated at Udawalawe Elephant Transit Home</li><li>Visit Asia’s largest Birds Park in Hambantota, home to thousands of birds and</li><li>many species</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[{"label":"Sri Lankan Leopard","image":"/YALA/Sri Lankan Leopard.jpg"},{"label":"Sloth Bear","image":"/YALA/Sloth Bear.jpg"},{"label":"Mugger Crocodile","image":"/YALA/Mugger Crocodile.jpg"},{"label":"Elephants in Sri Lanka","image":"/YALA/Elephants in Sri Lanka.jpg"},{"label":"Kataragama Hindu Temple","image":"/YALA/Kataragama Hindu Temple.jpg"},{"label":"Jungle Sundowner","image":"/YALA/Jungle Sundowner.webp"}]},{"title":"Day 10: Yala to Kalutara - Galle Fort and River Safari","description":"<ul><li>After breakfast, proceed to Bentota and Kalutara area</li><li>See Sri Lankan stilt fishermen in action, practicing their traditional craft</li><li>Visit beautiful Galle Fort and enjoy the Galle city tour</li><li>Enjoy a scenic boat ride through Madu River’s mangroves</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[{"label":"Stilt Fisherman","image":"/KALUTARA/Stilt Fisherman.jpg"},{"label":"Galle Fort","image":"/KALUTARA/Galle Fort.jpg"},{"label":"Turtle Conservation","image":"/KALUTARA/Turtle Conservation.jpg"},{"label":"Madu River Safari","image":"/KALUTARA/Madu River Safari.jpg"},{"label":"Water Sport","image":"/KALUTARA/Water Sport.jpg"},{"label":"Isolated Lighthouse","image":"/KALUTARA/Isolated Lighthouse.jpg"}]},{"title":"Day 11: Kalutara - Turtles, Water Sports, and Sunset Beach","description":"<ul><li>After breakfast at the hotel</li><li>Learn about Sri Lankan sea turtles at a turtle hatchery in Kosgoda</li><li>Enjoy exciting water sports in Bentota, including jet skiing, snorkeling, and deep-sea</li><li>fishing</li><li>Take a stroll along the calming beach and enjoy the spectacular sunset</li><li>Dinner and overnight stay at the hotel</li></ul>","highlights":[]},{"title":"Day 12: Kalutara to Colombo - City Highlights and Shopping","description":"<ul><li>After breakfast, proceed to Colombo</li><li>Visit Gangaramaya Temple and admire its blend of modern architecture and cultural</li><li>heritage</li><li>Visit Lotus Tower for breathtaking views of Colombo</li><li>Explore Galle Face Green and the historic Old Parliament building</li><li>Enjoy shopping at ODEL, Noritake, House of Fashion, tea shops, and local handicraft</li><li>stores</li><li>Overnight stay at the hotel</li></ul>","highlights":[]},{"title":"Day 13: Departure - Airport Drop-off","description":"<ul><li>Breakfast at the hotel</li><li>Transfer to the airport for departure (as per flight schedule)</li></ul>","highlights":[]}]$j$::jsonb,
