-- 23. romantic-bliss-15-days — Romantic Bliss (15 days)
INSERT INTO packages (slug, title, starting_price, description, days, inclusions, images, map_image, countries, destinations, themes, religions, activities, sort_order, is_published)
VALUES (
  $x$romantic-bliss-15-days$x$,
  $x$Romantic Bliss (15 days)$x$,
  $x$$6,190$x$,
  $x$<p>Duration: 15 days / 14 nights</p><p>Type: Tailor-made private honeymoon tour</p><p>Suitable For: Couples</p>$x$,
  $j$[{"title":"Day 1: Arrival - Negombo","description":"<ul><li>Arrival and transfer to Negombo (Kotugoda area)</li><li>Visit Muthurajawela Wetland (optional if time permits)</li><li>Sail on local fishing boats (experience-based, weather dependent)</li><li>Visit the churches in Negombo</li><li>Optional: Explore Negombo city, also known as Little Rome</li><li>Evening at leisure and unwind</li></ul>","highlights":[{"label":"Hamilton Canal","image":"/NEGOMBO/Hamilton Canal.jpg"},{"label":"Muthurajawela Wetland","image":"/NEGOMBO/Muthurajawela Wetland.jpg"},{"label":"Negombo Fish Market","image":"/NEGOMBO/Negombo Fish Market.jpg"},{"label":"Fishing Village Life","image":"/NEGOMBO/Fishing Village Life.jpg"},{"label":"Scenic Sunset","image":"/NEGOMBO/Scenic Sunset.jpg"},{"label":"Sail Boats","image":"/NEGOMBO/Sail Boats.jpg"}]},{"title":"Day 2: Negombo to Sigiriya - Caves and Sunset Viewpoint","description":"<ul><li>Transfer towards Sigiriya</li><li>Visit the Dambulla Cave Temple (UNESCO World Heritage Site)</li><li>Climb Pidurangala Rock for a spectacular sunset view over Sigiriya</li><li>Return to the hotel and relax</li></ul>","highlights":[{"label":"Sigiriya Rock Fortress","image":"/SIGIRIYA/Sigiriya Rock Fortress.jpg"},{"label":"Boat Ride Experience","image":"/SIGIRIYA/Boat Ride Experience.jpg"},{"label":"Safari at Minneriya","image":"/SIGIRIYA/Safari at Minneriya.jpg"},{"label":"Village Experience","image":"/SIGIRIYA/Village Experience.jpg"},{"label":"Piduranagala Rock","image":"/SIGIRIYA/Piduranagala Rock.jpg"},{"label":"Dambulla Cave Temple","image":"/SIGIRIYA/Dambulla Cave Temple.jpg"}]},{"title":"Day 3: Sigiriya - Fortress and Wildlife Safari","description":"<ul><li>Visit the UNESCO-listed Sigiriya Rock Fortress</li><li>Enjoy the beautiful water gardens, frescoes, and panoramic views from the top</li><li>Jeep safari at Minneriya National Park to spot wild elephants and other wildlife</li></ul>","highlights":[]},{"title":"Day 4: Sigiriya to Pussellawa via Kandy - City of Love","description":"<ul><li>Moments</li><li>Transfer to Pussellawa via Kandy</li><li>Visit the Temple of the Tooth Relic</li><li>Explore Kandy city</li><li>Visit the Royal Botanical Gardens in Peradeniya</li><li>Continue to Pussellawa and settle in</li></ul>","highlights":[]},{"title":"Day 5: Pussellawa - Tea Trails and High Tea","description":"<ul><li>Tea experiences with local tea pluckers</li><li>Visit Geradigini Ella Falls viewpoint</li><li>Explore Kotmale Reservoir or hike to the top of Peacock Hill</li><li>High tea session by the poolside</li></ul>","highlights":[]},{"title":"Day 6: Pussellawa - Ramayana Trail and Scenic Stops","description":"<ul><li>Visit the Hanuman Temple</li><li>Visit Kadadora Temple</li><li>Enjoy a scenic train ride (subject to availability)</li><li>Visit scenic waterfalls and hidden viewpoints</li></ul>","highlights":[]},{"title":"Day 7: Pussellawa to Ella - Boutique Stops and Tea Craft","description":"<ul><li>Transfer to Ella</li><li>Visit Adisham Bungalow en route</li><li>Free time at Ravana Pool Club</li><li>Try the Ella Swing for memorable photo moments</li><li>Visit Amba Estate and learn about artisanal tea-making</li></ul>","highlights":[]},{"title":"Day 8: Ella - Viewpoints, Waterfalls, and Adventure","description":"<ul><li>Visit Lipton’s Seat viewpoint for breathtaking views</li><li>Visit Upper Diyaluma Waterfall</li><li>Visit Ravana Waterfall</li><li>Explore the Nine Arches Bridge</li><li>Experience the Ravana zip-line for an adrenaline rush</li></ul>","highlights":[{"label":"Nine Arch Bridge","image":"/ELLA/ninearchbridge.jpg"},{"label":"Scenic Train Ride","image":"/ELLA/Scenictrainride.jpg"},{"label":"Tea Plantation Tours","image":"/ELLA/Teaplantationtours.jpg"},{"label":"Ella Rock","image":"/ELLA/ellarock.jpg"},{"label":"Waterfall Visits","image":"/ELLA/Waterfallvisiots.jpg"},{"label":"Zip-lining","image":"/ELLA/Zip-lining.jpg"}]},{"title":"Day 9: Ella to Yala - Elephants and Safari Night","description":"<ul><li>Transfer to Yala</li><li>Visit the Elephant Transit Home (baby elephant rehabilitation project)</li><li>Jeep safari at Yala National Park, with chances to spot Sri Lankan leopards and</li><li>other wildlife</li></ul>","highlights":[]},{"title":"Day 10: Yala - Nature Trails and Romance Under the Stars","description":"<ul><li>Bird watching trail with a resident naturalist</li><li>Second jeep safari at Yala National Park for more wildlife encounters</li><li>Romantic dinner on the beach under the stars</li></ul>","highlights":[{"label":"Sri Lankan Leopard","image":"/YALA/Sri Lankan Leopard.jpg"},{"label":"Sloth Bear","image":"/YALA/Sloth Bear.jpg"},{"label":"Mugger Crocodile","image":"/YALA/Mugger Crocodile.jpg"},{"label":"Elephants in Sri Lanka","image":"/YALA/Elephants in Sri Lanka.jpg"},{"label":"Kataragama Hindu Temple","image":"/YALA/Kataragama Hindu Temple.jpg"},{"label":"Jungle Sundowner","image":"/YALA/Jungle Sundowner.webp"}]},{"title":"Day 11: Yala to Tangalle - Beach Time and Turtle Nesting","description":"<ul><li>Transfer to Tangalle</li><li>Leisure time at the beach to relax and unwind</li><li>Optional wellness and spa treatments</li><li>Turtle nesting experience at night (seasonal and nature dependent)</li></ul>","highlights":[{"label":"Relaxing at Beach","image":"/TANGALLE/Relaxing at Beach.jpg"},{"label":"Elephant Transit Home","image":"/TANGALLE/Elephant Transit Home.jpg"},{"label":"Mulgirigala","image":"/TANGALLE/Mulgirigala.jpg"},{"label":"Bird Sanctuary","image":"/TANGALLE/Bird Sanctuary.jpg"},{"label":"Kayaking","image":"/TANGALLE/Kayaking.jpg"},{"label":"Traditional Food","image":"/TANGALLE/Traditional Food.jpg"}]},{"title":"Day 12: Tangalle - Caves and Lagoon Sunset","description":"<ul><li>Visit Mulgirigala Caves and explore ancient murals</li><li>Sunset boat ride at Kalametiya Lagoon sanctuary</li></ul>","highlights":[]},{"title":"Day 13: Tangalle to Galle - Coastal Icons","description":"<ul><li>Transfer to Galle</li><li>Stop at Mirissa and Coconut Tree Hill for iconic views</li><li>Visit the stilt fishermen in Ahangama</li><li>Optional: Try the stilt fishing pose if weather and conditions allow</li></ul>","highlights":[]},{"title":"Day 14: Galle - Fort Walk and Sundowners","description":"<ul><li>Guided walk inside the Royal Dutch Fort in Galle</li><li>Visit the Dutch Reformed Church</li><li>Sundowners at Galle Fort overlooking the ramparts</li></ul>","highlights":[{"label":"Galle Fort","image":"/GALLE/gallfort.jpg"},{"label":"Historic Streets","image":"/GALLE/historic-streets.jpg"},{"label":"Fort Museums","image":"/GALLE/Fort Museums.jpg"},{"label":"Beach Activities","image":"/GALLE/Beach Activities.jpg"},{"label":"Local Market & Shopping","image":"/GALLE/localmarketshopppign.jpg"},{"label":"Sunset Rampart Walks","image":"/GALLE/sunsetrampartwalks.jpg"}]},{"title":"Day 15: Departure - Airport Drop-off","description":"<ul><li>Breakfast at the hotel</li><li>Transfer to the airport for departure (as per flight schedule)</li></ul>","highlights":[]}]$j$::jsonb,
